import sys
import heapq

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        n = int(next(iterator))
        m = int(next(iterator))
        q = int(next(iterator))

        w = [0] * (n + 1)
        for i in range(1, n + 1):
            w[i] = int(next(iterator))

        adj = [[] for _ in range(n + 1)]
        for _ in range(m):
            u = int(next(iterator))
            v = int(next(iterator))
            d = int(next(iterator))
            adj[u].append((v, d))
            adj[v].append((u, d))

        dist = [-1] * (n + 1)
        pq = [(0, 1)]
        dist[1] = 0

        while pq:
            d_val, u = heapq.heappop(pq)
            if d_val > dist[u] and dist[u] != -1:
                continue
            if d_val < dist[u] or dist[u] == -1:
                dist[u] = d_val
                for v, weight in adj[u]:
                    if dist[v] == -1 or dist[v] > dist[u] + weight:
                        heapq.heappush(pq, (dist[u] + weight, v))

        first_count = [0] * (n + 1)
        second_count = [0] * (n + 1)

        for i in range(2, n + 1):
            for v, weight in adj[i]:
                if dist[v] != -1 and dist[i] != -1:
                    if dist[v] + weight == dist[i]:
                        if dist[v] == 0:
                            first_count[i] += 1
                        else:
                            second_count[i] += 1

        current_w = list(w)
        total_cost = 0
        for i in range(2, n + 1):
            if first_count[i] >= 2:
                continue
            elif first_count[i] == 1:
                if second_count[i] >= 1:
                    continue
                else:
                    total_cost += current_w[i]
            else:
                if second_count[i] >= 2:
                    continue
                elif second_count[i] == 1:
                    total_cost += current_w[i]
                else:
                    total_cost += current_w[i]

        results = []
        results.append(str(total_cost))

        for _ in range(q):
            k = int(next(iterator))
            x = int(next(iterator))
            current_w[k] += x

            new_total = 0
            for i in range(2, n + 1):
                if first_count[i] >= 2:
                    continue
                elif first_count[i] == 1:
                    if second_count[i] >= 1:
                        continue
                    else:
                        new_total += current_w[i]
                else:
                    if second_count[i] >= 2:
                        continue
                    elif second_count[i] == 1:
                        new_total += current_w[i]
                    else:
                        new_total += current_w[i]
            results.append(str(new_total))

        sys.stdout.write('\n'.join(results) + '\n')

    except StopIteration:
        pass

if __name__ == "__main__":
    solve()
